import{_ as e,c as d,a0 as r,o}from"./chunks/framework.DyATOcH3.js";const b=JSON.parse('{"title":"Functional Specifications","description":"","frontmatter":{},"headers":[],"relativePath":"specs/functional-spec.md","filePath":"specs/functional-spec.md"}'),a={name:"specs/functional-spec.md"};function i(s,t,n,c,l,u){return o(),d("div",null,t[0]||(t[0]=[r('<h1 id="functional-specifications" tabindex="-1">Functional Specifications <a class="header-anchor" href="#functional-specifications" aria-label="Permalink to &quot;Functional Specifications&quot;">​</a></h1><p>This specification serves as a blueprint to guide us in developing the right product for the right market. It is not based on shallow assumptions but rather the result of a deliberate and thorough analysis of real-world problems, ensuring that the product addresses the actual needs and challenges of its users.</p><p><strong>Functional Specification</strong></p><table tabindex="0"><thead><tr><th>ID</th><th>Name</th><th>Description</th><th>Steps</th><th>Expect</th></tr></thead><tbody><tr><td>A001</td><td>View menu</td><td>Enable users to view restaurant menu from their mobile phone</td><td>Open link from the QR code given<br></td><td>Navigated to restaurant menu list</td></tr><tr><td>A002</td><td>Category</td><td>Enables users to view menu categorically by navigating through selecting category.</td><td>From A001<br>Navigate to category page by clicking available buttons<br></td><td>Navigated to categorize menu list</td></tr><tr><td>A003</td><td>Add Item Quick Button</td><td>Allows users to add item from the menu page to quickly add them</td><td>From A001 / A002<br>Click &#39;+&#39; on item card<br>Click &#39;-&#39; to decrease quantity<br></td><td>Shows item has been added in bottom sheet dialog with quantity</td></tr><tr><td>A004</td><td>Sign member if any</td><td>Force customer to sign or register as member to continue according to restaurant policy</td><td></td><td></td></tr><tr><td>B001</td><td>Item detail</td><td>Allows user to see item details</td><td>From A001 / A002<br>Click menu item card<br></td><td>Navigate to item detail page</td></tr><tr><td>B002</td><td>Add Item from detail page</td><td>Allows user to add item according to its quantity</td><td>From B001<br>Click add item<br>Button &#39;-&#39; and &#39;+&#39; was enabled if quantity &gt; 0<br></td><td>Item added to chart</td></tr><tr><td>C001</td><td>View ordered items in cart page</td><td>Continue to orders page to view ordered items</td><td>From A001 / A002<br>Have item total quantity &gt; 0<br>Click checkout on bottom sheet<br>Or click cart item on nav bar<br></td><td>Navigate to cart page and enable user to view ordered items and the total.</td></tr><tr><td>C002</td><td>Checkout order</td><td>Continue to checkout page consists of customer&#39;s current ordered items</td><td>From C001<br>Click checkout button to create order<br>Input table number optionally<br>Optionally add notes<br></td><td>Queues customer order and navigate to order detail page</td></tr><tr><td>D001</td><td>Order detail</td><td>Enables customer to view details of their order including queue status and order status</td><td>From C002<br>or navigating from nav bar button<br></td><td>Displays<br>Ordered items<br>Queue status<br>Order status (out of order, in order)<br>QR code of order ID<br>Total cost including tax<br></td></tr><tr><td>D002</td><td>Order list</td><td>Enable customer to view orders have been made</td><td>From A001 / A002<br></td><td>Display list of customer&#39;s order</td></tr><tr><td>E001</td><td>Receptionist order page</td><td>Display customer order list categorized by In order or In queue</td><td>Login as staff member<br></td><td>Display list of orders that have been made</td></tr><tr><td>E002</td><td>Order detail</td><td>Display customer&#39;s order detail</td><td>From E001<br>Click order card<br></td><td>Display order detail</td></tr><tr><td>E003</td><td>Take order</td><td>Move order to In order status. This means the order is currently handled by the kitchen.</td><td>From E002<br>Click Take order<br></td><td>Update order status. Customer also notified by this changes.</td></tr><tr><td>E004</td><td>Out of order</td><td>Happens when some item is out of order. The staff select the item is out of order. The default message is Out of order, the staff can input custom message</td><td>E002<br>Click drop order<br>Select item that will be dropped<br>If item selected, input message optionally<br></td><td>The order status is changed to out of order. The customer is notified by this changes</td></tr><tr><td>E005</td><td>Search order</td><td>Search order by ID. Showed by customer from D001 when they want to pay at the cashier. Cashier can use barcode scanner.</td><td>From E001<br>Click search icon<br></td><td>Found an order detail by the given ID</td></tr><tr><td>E006</td><td>Find orders by table</td><td>Find order by table</td><td>From E001<br>Navigate to `table` tab<br></td><td>Found all orders that have been made with associated table</td></tr><tr><td>E007</td><td>Find orders by customer name</td><td>Find order by customer name</td><td>From E001<br>Navigate to `customer` tab<br></td><td>Found all orders that have been made with associated customer</td></tr><tr><td>E008</td><td>Show receipt</td><td>Show order receipt</td><td>From E002<br>Click receipt<br></td><td>Show order receipt</td></tr><tr><td>E009</td><td>Show receipt by table</td><td>Show merged order receipt by table</td><td>From E006<br>Click `table` card<br>Click show receipt<br></td><td>Show merged orders receipt by associated table</td></tr><tr><td>E010</td><td>Show receipt by customer name</td><td>Show merged order receipt by customer name</td><td>From E007<br>Click `customer` card<br>Click show receipt<br></td><td>Show merged orders receipt by associated customer name</td></tr><tr><td>E011</td><td>Update order (multiple/single) status to paid</td><td>Update status to paid</td><td></td><td></td></tr><tr><td>E012</td><td>Update order status (single) to serve</td><td>Update status to served</td><td></td><td></td></tr><tr><td>F001</td><td>Item status manipulation</td><td>Update menu item stock status</td><td></td><td></td></tr></tbody></table>',4)]))}const h=e(a,[["render",i]]);export{b as __pageData,h as default};
